    const tools = records.filter(r => r.type === "item.completed" && r.item?.type !== "agent_message").map(r => ({ type: r.item?.type, id: r.item?.id, status: r.item?.status, exitCode: r.item?.exit_code, command: r.item?.command ?? null }));
